Arguments: {"title":"Inspect filter checkboxes","cwd":null,"code":"const tabId = 118779795;

const filterInfo = await browserjs(tabId, () => {
  const filterRegion = document.querySelector('[aria-label="Search Filters"]') || document.body;
  const headings = Array.from(filterRegion.querySelectorAll('h2, h3, legend, .filter-section-header, label')).map(el => el.textContent?.trim());

  // Find all checkboxes and labels
  const checkboxes = Array.from(filterRegion.querySelectorAll('input[type="checkbox"], [role="checkbox"]')).map(cb => {
    const label = cb.closest('label')?.textContent?.trim() || cb.getAttribute('aria-label') || cb.id;
    return { label, checked: cb.checked || cb.getAttribute('aria-checked') };
  });

  return { headings: headings.slice(0, 30), checkboxes };
});

console.log("Checkboxes found:", filterInfo.checkboxes.length);
console.log(JSON.stringify(filterInfo.checkboxes, null, 2));
"}
